isOpen.example:
if (!db.isOpen) {
  console.warn('the shop database is closed');
}

isOpen.exampleCs:
if (!db.IsOpen)
{
    Log.Warn("the shop database is closed");
}

query.example:
for (const row of db.query('SELECT item, price FROM prices WHERE price < ?', [50])) {
  console.log(`${row.item}: ${row.price}`);
}

query.exampleCs:
foreach (var row in db.Query("SELECT item, price FROM prices WHERE price < ?", new object[] { 50 }))
{
    Log.Info($"{row["item"]}: {row["price"]}");
}

exec.example:
db.exec(`
  CREATE TABLE IF NOT EXISTS prices (item TEXT PRIMARY KEY, price INTEGER);
  CREATE INDEX IF NOT EXISTS prices_by_price ON prices (price);
`);

exec.exampleLua:
db:exec([[
  CREATE TABLE IF NOT EXISTS prices (item TEXT PRIMARY KEY, price INTEGER);
  CREATE INDEX IF NOT EXISTS prices_by_price ON prices (price);
]])

exec.exampleCs:
db.Exec(@"
  CREATE TABLE IF NOT EXISTS prices (item TEXT PRIMARY KEY, price INTEGER);
  CREATE INDEX IF NOT EXISTS prices_by_price ON prices (price);
");

transaction.example:
db.transaction(() => {
  db.run('UPDATE prices SET price = price + 1');
  db.run('INSERT OR REPLACE INTO prices VALUES (?, ?)', ['nails', 2]);
});

transaction.exampleCs:
db.Transaction(() =>
{
    db.Run("UPDATE prices SET price = price + 1");
    db.Run("INSERT OR REPLACE INTO prices VALUES (?, ?)", new object[] { "nails", 2 });
});
